(* [comment removed for export] *)
Lemma apply_zeros_same : forall (m : amem) A L a n,
  rw_cells bsegs m A [CB (Z.to_nat L) (zeros L)] -> 0 <= L ->
  0x60f000 <= A -> A <= a -> 0 < n -> a + n <= A + L ->
  apply_zeros m [(wa a, Z_to_bv 64 n)] = m.
Proof.
